// ---------------------------------------------------------------------------
// Coordinate convention
//   file a..h  -> x = 0..7
//   rank 1..8  -> z = 0..7
//   each square is a 1x1 tile centered on integer (x, z)
//   board top surface is y = 0 (tiles are centered at y = -TILE_H / 2)
// ---------------------------------------------------------------------------

export const FILES = 'abcdefgh';
export const TILE_SIZE = 1;
export const TILE_HEIGHT = 0.25;

const LIGHT_COLOR = 0xf0d9b5;
const DARK_COLOR = 0xb58863;
const WHITE_PIECE_COLOR = 0xf5f0e1;
const BLACK_PIECE_COLOR = 0x2b2b2b;

/** x/z center of a square like "a1" or "d8" (y is always 0 for the board top). */
export function squarePosition(file, rank) {
  return new THREE.Vector3(FILES.indexOf(file), 0, rank - 1);
}

function squareName(file, rank) {
  return `${FILES[file]}${rank}`;
}

// ---------------------------------------------------------------------------
// Primitive helpers
// ---------------------------------------------------------------------------

const whiteMaterial = () => new THREE.MeshStandardMaterial({ color: WHITE_PIECE_COLOR, roughness: 0.55 });
const blackMaterial = () => new THREE.MeshStandardMaterial({ color: BLACK_PIECE_COLOR, roughness: 0.55 });

function lathe(points, material) {
  const profile = points.map(([x, y]) => new THREE.Vector2(Math.max(x, 0), y));
  const mesh = new THREE.Mesh(new THREE.LatheGeometry(profile, 32), material);
  return mesh;
}

function cyl(rTop, rBottom, height, yCenter, material, segments = 24) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(rTop, rBottom, height, segments), material);
  mesh.position.y = yCenter;
  return mesh;
}

function ball(radius, yCenter, material, x = 0, z = 0) {
  const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, 24, 16), material);
  mesh.position.set(x, yCenter, z);
  return mesh;
}

function box(w, h, d, x, y, z, material) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
  mesh.position.set(x, y, z);
  return mesh;
}

/**
 * Turned base shared by the "lathe" pieces: a plinth that flares at the
 * bottom, a waist, and a small collar. Returns { mesh, topY }.
 */
function turnedBase(height, maxRadius, material) {
  const p = [
    [0.000, 0],
    [maxRadius, 0],
    [maxRadius, 0.06 * height],
    [maxRadius * 0.72, 0.14 * height],
    [maxRadius * 0.45, 0.45 * height],
    [maxRadius * 0.52, 0.58 * height],
    [maxRadius * 0.30, 0.66 * height],
    [maxRadius * 0.34, 0.74 * height],
    [maxRadius * 0.16, 0.80 * height],
    [0.000, 0.82 * height],
  ];
  return lathe(p, material);
}

// ---------------------------------------------------------------------------
// Pieces — every make*() returns a Group whose origin sits at the piece's
// base (y = 0), standing directly on the board top surface.
// ---------------------------------------------------------------------------

function makePawn(material) {
  const g = new THREE.Group();
  g.add(turnedBase(0.44, 0.15, material));            // body up to ~0.36
  g.add(ball(0.095, 0.475, material));                // head -> top ~0.57
  return g; // height ~0.57
}

function makeRook(material) {
  const g = new THREE.Group();
  g.add(cyl(0.19, 0.22, 0.10, 0.05, material));       // plinth
  g.add(cyl(0.13, 0.17, 0.50, 0.35, material));       // tower shaft -> 0.60
  g.add(cyl(0.18, 0.18, 0.08, 0.64, material));       // crown band  -> 0.68
  // crenellations
  for (let i = 0; i < 4; i++) {
    const a = (i / 4) * Math.PI * 2 + Math.PI / 4;
    g.add(box(0.09, 0.09, 0.09, Math.cos(a) * 0.12, 0.725, Math.sin(a) * 0.12, material));
  }
  return g; // height ~0.77
}

function makeKnight(material) {
  // Stylized knight built from boxes: pedestal, angled neck, head, ears, muzzle.
  const g = new THREE.Group();
  g.add(box(0.36, 0.12, 0.36, 0, 0.06, 0, material));          // pedestal
  const neck = box(0.20, 0.46, 0.24, 0, 0.35, -0.02, material);
  neck.rotation.x = -0.28;
  g.add(neck);                                                  // neck -> ~0.62
  g.add(box(0.20, 0.20, 0.40, 0, 0.63, 0.07, material));       // head     -> ~0.73
  g.add(box(0.12, 0.14, 0.14, 0, 0.76, 0.20, material));       // muzzle   -> ~0.83
  g.add(box(0.06, 0.10, 0.08, -0.06, 0.79, -0.10, material));  // ear
  g.add(box(0.06, 0.10, 0.08, 0.06, 0.79, -0.10, material));   // ear      -> ~0.84
  return g; // height ~0.84
}

function makeBishop(material) {
  const g = new THREE.Group();
  g.add(turnedBase(0.66, 0.17, material));            // body up to ~0.54
  g.add(cyl(0.02, 0.11, 0.14, 0.61, material));       // taper into head -> 0.68
  g.add(ball(0.105, 0.78, material));                 // mitre      -> 0.885
  g.add(ball(0.035, 0.925, material));                // finial     -> ~0.96
  return g; // height ~0.96
}

function makeQueen(material) {
  const g = new THREE.Group();
  g.add(turnedBase(0.92, 0.20, material));            // tall body up to ~0.75
  g.add(cyl(0.03, 0.13, 0.16, 0.82, material));       // collar -> 0.90
  g.add(ball(0.115, 1.00, material));                 // crown  -> 1.115
  g.add(ball(0.035, 1.145, material));               // orb     -> ~1.18
  return g; // height ~1.18
}

function makeKing(material) {
  const g = new THREE.Group();
  g.add(turnedBase(1.04, 0.21, material));            // tallest body -> ~0.85
  g.add(cyl(0.03, 0.14, 0.16, 0.93, material));       // collar -> 1.01
  g.add(ball(0.12, 1.10, material));                  // head   -> 1.22
  g.add(box(0.035, 0.22, 0.10, 0, 1.33, 0, material)); // cross vertical -> 1.44
  g.add(box(0.12, 0.035, 0.10, 0, 1.36, 0, material)); // cross arm
  return g; // height ~1.44
}

const PIECE_BUILDERS = {
  pawn: makePawn,
  rook: makeRook,
  knight: makeKnight,
  bishop: makeBishop,
  queen: makeQueen,
  king: makeKing,
};

export const PIECE_TYPES = Object.keys(PIECE_BUILDERS);

/**
 * Build a chess piece of the given type ("pawn" | "rook" | "knight" |
 * "bishop" | "queen" | "king"). Returns a Group whose bounding-box height
 * follows pawn < rook < knight <= bishop < queen < king.
 */
export function makePiece(type) {
  const builder = PIECE_BUILDERS[type];
  if (!builder) throw new Error(`Unknown piece type: ${type}`);
  const group = builder(whiteMaterial());
  group.userData.pieceType = type;
  return group;
}

function makePieceForColor(type, color) {
  const material = color === 'w' ? whiteMaterial() : blackMaterial();
  return PIECE_BUILDERS[type](material);
}

// ---------------------------------------------------------------------------
// Board setup
// ---------------------------------------------------------------------------

/** Standard back-rank order from file a to h. */
const BACK_RANK = ['rook', 'knight', 'bishop', 'queen', 'king', 'bishop', 'knight', 'rook'];

/**
 * Build the full starting position:
 * an 8x8 board of alternating 1x1 tiles plus all 32 pieces.
 * Tiles are named "tile-a1" ... "tile-h8"; pieces "w-pawn-a2", "b-king-e8", ...
 */
export function setupBoard() {
  const board = new THREE.Group();
  board.name = 'chessboard';

  const lightTileMat = new THREE.MeshStandardMaterial({ color: LIGHT_COLOR, roughness: 0.7 });
  const darkTileMat = new THREE.MeshStandardMaterial({ color: DARK_COLOR, roughness: 0.7 });

  for (let f = 0; f < 8; f++) {
    for (let r = 1; r <= 8; r++) {
      const pos = squarePosition(FILES[f], r);
      const isDark = (f + r - 1) % 2 === 0; // a1 dark

      const tile = new THREE.Mesh(
        new THREE.BoxGeometry(TILE_SIZE, TILE_HEIGHT, TILE_SIZE),
        isDark ? darkTileMat : lightTileMat,
      );
      tile.name = `tile-${squareName(f, r)}`;
      tile.position.set(pos.x, -TILE_HEIGHT / 2, pos.z);
      tile.userData.isDark = isDark;
      board.add(tile);

      // pieces on their standard starting squares
      let type = null;
      if (r === 1 || r === 8) type = BACK_RANK[f];
      else if (r === 2 || r === 7) type = 'pawn';
      if (!type) continue;

      const color = r <= 2 ? 'w' : 'b';
      const piece = makePieceForColor(type, color);
      piece.name = `${color}-${type}-${squareName(f, r)}`;
      piece.userData.pieceType = type;
      piece.userData.color = color;
      piece.position.copy(pos); // base sits exactly on the square's center
      board.add(piece);
    }
  }

  return board;
}
"})
