result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test/chess.test.js", "content": "import { describe, it, expect } from 'vitest';
import * as THREE from 'three';
import { makePiece, setupBoard, FILES, squarePosition } from '../src/chess.js';

function pieceHeight(type) {
  const group = makePiece(type);
  group.updateMatrixWorld(true);
  return new THREE.Box3().setFromObject(group).getSize(new THREE.Vector3()).y;
}

describe('piece height ordering', () => {
  it('follows pawn < rook < knight <= bishop < queen < king', () => {
    const heights = {
      pawn: pieceHeight('pawn'),
      rook: pieceHeight('rook'),
      knight: pieceHeight('knight'),
      bishop: pieceHeight('bishop'),
      queen: pieceHeight('queen'),
      king: pieceHeight('king'),
    };
    expect(heights.pawn).toBeGreaterThan(0);
    expect(heights.rook).toBeGreaterThan(heights.pawn);
    expect(heights.knight).toBeGreaterThanOrEqual(heights.rook);
    expect(heights.bishop).toBeGreaterThanOrEqual(heights.knight);
    expect(heights.queen).toBeGreaterThan(heights.bishop);
    expect(heights.king).toBeGreaterThan(heights.queen);
  });
});

describe('board structure', () => {
  const board = setupBoard();

  it('contains exactly 64 tiles', () => {
    const tiles = board.children.filter((c) => c.name.startsWith('tile-'));
    expect(tiles).toHaveLength(64);
    for (const t of tiles) expect(t.isMesh).toBe(true);
  });

  it('contains exactly 32 pieces', () => {
    const pieces = board.children.filter((c) => /^[wb]-/.test(c.name));
    expect(pieces).toHaveLength(32);
    for (const p of pieces) expect(p.isGroup).toBe(true);
  });

  it('places b-queen-d8 at the center of d8 within 1e-9', () => {
    const expected = squarePosition('d', 8); // x = 3 (d), z = 7 (rank 8)
    const queen = board.getObjectByName('b-queen-d8');
    expect(queen).toBeDefined();
    expect(queen.position.x).toBeCloseTo(expected.x, 9);
    expect(queen.position.z).toBeCloseTo(expected.z, 9);
    expect(Math.abs(queen.position.x - expected.x)).toBeLessThanOrEqual(1e-9);
    expect(Math.abs(queen.position.z - expected.z)).toBeLessThanOrEqual(1e-9);
  });

  it('keeps white pieces on ranks 1 and 2 only', () => {
    const whites = board.children.filter((c) => c.name.startsWith('w-'));
    expect(whites).toHaveLength(16);
    for (const p of whites) {
      const rank = Math.floor(p.position.z) + 1;
      expect([1, 2]).toContain(rank);
    }
  });

  it('alternates tile colors with a1 dark', () => {
    const dark = new THREE.Color(0xb58863);
    const light = new THREE.Color(0xf0d9b5);
    for (let f = 0; f < 8; f++) {
      for (let r = 1; r <= 8; r++) {
        const tile = board.getObjectByName(`tile-${FILES[f]}${r}`);
        expect(tile).toBeDefined();
        const shouldBeDark = (f + r - 1) % 2 === 0;
        expect(tile.userData.isDark).toBe(shouldBeDark);
        const expected = shouldBeDark ? dark : light;
        expect(tile.material.color.equals(expected)).toBe(true);
      }
    }
    // explicit anchor: a1 must be dark
    const a1 = board.getObjectByName('tile-a1');
    expect(a1.material.color.equals(dark)).toBe(true);
  });

  it('has every standard starting piece named and placed correctly', () => {
    const backRank = ['rook', 'knight', 'bishop', 'queen', 'king', 'bishop', 'knight', 'rook'];
    let count = 0;
    for (let f = 0; f < 8; f++) {
      for (const [rank, type] of [[1, backRank[f]], [2, 'pawn'], [7, 'pawn'], [8, backRank[f]]]) {
        const color = rank <= 2 ? 'w' : 'b';
        const name = `${color}-${type}-${FILES[f]}${rank}`;
        const piece = board.getObjectByName(name);
        expect(piece, name).toBeDefined();
        const expected = squarePosition(FILES[f], rank);
        expect(piece.position.x).toBeCloseTo(expected.x, 9);
        expect(piece.position.z).toBeCloseTo(expected.z, 9);
        count++;
      }
    }
    expect(count).toBe(32);
  });
});
"})
